class AgentasticBeta < Formula
  desc "Agentastic coding agent CLI (beta channel)"
  homepage "https://www.agentastic.dev"
  version "0.20.2"
  license "Apache-2.0"

  BASE = "https://releases.agentastic.ai/agent/v0.20.2".freeze

  # Homebrew loads every declared conflict, even when it is not installed. Only
  # inspect active kegs so upgrading one trusted train does not require trusting
  # the other trains (or loading a nightly formula that has not been published).
  ["agentastic", "agentastic-nightly"].each do |name|
    next unless (HOMEBREW_PREFIX/"var/homebrew/linked"/name).exist? && (HOMEBREW_PREFIX/"opt"/name).exist?

    conflicts_with "agentasticai/tap/#{name}",
      because: "every Agentastic release train installs the `agentastic` command"
  end

  on_macos do
    on_arm do
      url "#{BASE}/agentastic-0.20.2-aarch64-apple-darwin.tar.gz"
      sha256 "d32752e1afcf3aec55ff2f0920e1100657cf9919edbd580d61b351f7ce2a247b"
    end
    on_intel do
      url "#{BASE}/agentastic-0.20.2-x86_64-apple-darwin.tar.gz"
      sha256 "d9e8db098ba3f4f7c4a1a7bec95bf633011fbf1bd00dc43d1de42b0b8aecd08d"
    end
  end

  on_linux do
    on_arm do
      url "#{BASE}/agentastic-0.20.2-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "3f6633d37da534d1a2ed94a43b63a2064489c60f25fee82c1d4d7f1214f4f691"
    end
    on_intel do
      url "#{BASE}/agentastic-0.20.2-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "ae659e5c3034decb2d3197de13ff2a47a807a6cfee1aa2a7c72ae05b19efaced"
    end
  end

  def install
    # Tarball holds two stripped binaries: the CLI and the code-mode host, which the
    # CLI spawns from its own bin dir under that exact name. The background daemon
    # installs its app server only from a complete package (both binaries plus this
    # metadata), so keep them together in libexec, apart from the keg's receipts.
    # `channel` is the train `agentastic` keeps upgrading along.
    (libexec/"bin").install "agentastic", "agentastic-code-mode-host"
    triple = "#{Hardware::CPU.arm? ? "aarch64" : "x86_64"}-#{OS.mac? ? "apple-darwin" : "unknown-linux-gnu"}"
    (libexec/"agentastic-package.json").write <<~JSON
      {"layoutVersion":1,"version":"#{version}","target":"#{triple}","variant":"agentastic","entrypoint":"bin/agentastic","resourcesDir":"agentastic-resources","pathDir":"agentastic-path","channel":"beta"}
    JSON
    bin.install_symlink libexec/"bin/agentastic" => "agentastic"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/agentastic --version")
  end
end
